// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/mint/IStreamMintCounterReads.sol";
import "../../interfaces/stream/mint/IStreamMintReads.sol";
import "./StreamMintManagerAccounting.sol";

/// @notice Fixed counter-only reads in Manager context; these never establish mint authority.
library StreamMintCounterReads {
    /// @notice Fixed dispatch for five counter reads and four retained accounting reads.
    /// @dev The facade passes its original calldata explicitly; library msg.data is never used.
    function read(bytes calldata callData) external view returns (bytes memory) {
        bytes4 selector = bytes4(callData[:4]);
        bytes calldata arguments = callData[4:];
        if (selector == IStreamMintReads.isAuthorizationUsed.selector) {
            return abi.encode(
                IStreamMintReads(address(this)).mintLedger()
                    .isManagerAuthorizationUsed(address(this), abi.decode(arguments, (bytes32)))
            );
        }
        if (selector == IStreamMintReads.isNullifierUsed.selector) {
            return abi.encode(
                IStreamMintReads(address(this)).mintLedger()
                    .isManagerNullifierUsed(address(this), abi.decode(arguments, (bytes32)))
            );
        }
        if (selector == IStreamMintReads.isOperationRootUsed.selector) {
            return abi.encode(
                IStreamMintReads(address(this)).mintLedger()
                    .isManagerOperationRootUsed(address(this), abi.decode(arguments, (bytes32)))
            );
        }
        if (selector == IStreamMintReads.phasePolicyGrace.selector) {
            (uint256 collectionId, bytes32 phaseId) = abi.decode(arguments, (uint256, bytes32));
            (bytes32 previousPolicyHash,, uint64 graceUntil) = IStreamMintReads(address(this))
                .mintLedger().policyGrace(address(this), collectionId, phaseId);
            return abi.encode(previousPolicyHash, graceUntil);
        }
        if (selector == IStreamMintCounterReads.rawCounterValue.selector) {
            return abi.encode(
                IStreamMintReads(address(this)).mintLedger()
                    .counterValue(abi.decode(arguments, (bytes32)))
            );
        }
        if (
            selector == IStreamMintCounterReads.counterValue.selector
                || selector == IStreamMintCounterReads.remainingForCounter.selector
        ) {
            return abi.encode(
                _valueRead(
                    arguments, selector == IStreamMintCounterReads.remainingForCounter.selector
                )
            );
        }
        // No user-supplied target, call, storage location or selector outside this fixed table.
        assert(
            selector == IStreamMintCounterReads.resolveCounter.selector
                || selector == IStreamMintCounterReads.remainingForResolvedCounter.selector
        );
        return _resolveEncoded(
            arguments, selector == IStreamMintCounterReads.remainingForResolvedCounter.selector
        );
    }

    /// @notice Decodes the original four-word counter read at the fixed boundary.
    function _valueRead(bytes calldata arguments, bool withRemaining)
        private
        view
        returns (uint64)
    {
        (uint256 collectionId, bytes32 phaseId, bytes32 counterId, bytes32 subject) =
            abi.decode(arguments, (uint256, bytes32, bytes32, bytes32));
        IStreamMintManager.MintCounterConfig memory config =
            _config(collectionId, phaseId, counterId);
        if (withRemaining && config.capMode == IStreamMintLedger.CounterCapMode.MERKLE_STATIC) {
            revert IStreamMintCounterReads.MintCounterProofRequired(counterId);
        }
        uint64 current = _value(collectionId, phaseId, counterId, subject);
        return withRemaining ? _remaining(config.capMode, config.staticCap, current) : current;
    }

    /// @notice Returns the exact static 128/192-byte caller ABI without facade tuple re-encoding.
    function _resolveEncoded(bytes calldata arguments, bool withRemaining)
        private
        view
        returns (bytes memory)
    {
        IStreamMintCounterReads.CounterKeyContext memory x =
            abi.decode(arguments, (IStreamMintCounterReads.CounterKeyContext));
        (
            IStreamMintCounterReads.CounterResolution memory resolution,
            uint64 current,
            uint64 remainingUnits
        ) = _resolve(x);
        return
            withRemaining ? abi.encode(resolution, current, remainingUnits) : abi.encode(resolution);
    }

    function _resolve(IStreamMintCounterReads.CounterKeyContext memory x)
        private
        view
        returns (
            IStreamMintCounterReads.CounterResolution memory result,
            uint64 current,
            uint64 allowance
        )
    {
        IStreamMintManager.MintCounterConfig memory config =
            _config(x.collectionId, x.phaseId, x.counterId);
        bool batchScoped = config.keyMode == IStreamMintManager.CounterKeyMode.CONTEXT;
        if (batchScoped ? x.tokenIndex != type(uint256).max : x.tokenIndex >= 10) {
            revert IStreamMintCounterReads.MintCounterTokenIndexInvalid(x.counterId, x.tokenIndex);
        }
        address ledger = address(IStreamMintReads(address(this)).mintLedger());
        StreamMintOperationIdentity.CounterContext memory counterContext =
            StreamMintOperationIdentity.CounterContext(
                block.chainid, address(this), ledger, x.executor, x.authorizer
            );
        IStreamMintLedger.CounterConsumption memory row =
            StreamMintOperationIdentity.counterConsumption(
                StreamMintOperationIdentity.SubjectContext(
                    block.chainid,
                    ledger,
                    x.collectionId,
                    x.phaseId,
                    x.counterId,
                    x.payer,
                    batchScoped ? address(0) : x.beneficiary,
                    x.executor,
                    x.authorizer,
                    x.contextHash
                ),
                config,
                x.tokenIndex,
                counterContext
            );
        row = StreamMintCounterPreparation.resolveCounter(
            row, config, counterContext, x.resolverData
        );
        result = IStreamMintCounterReads.CounterResolution(
            row.subjectKey, row.cap, row.increment, row.resolutionHash
        );
        current = IStreamMintLedger(ledger).counterValue(row.valueKey);
        allowance = _remaining(config.capMode, row.cap, current);
    }

    function _config(uint256 collectionId, bytes32 phaseId, bytes32 counterId)
        private
        view
        returns (IStreamMintManager.MintCounterConfig memory config)
    {
        if (collectionId == 0 || phaseId == bytes32(0)) {
            revert IStreamMintManager.InvalidMintPhase(collectionId, phaseId);
        }
        IStreamMintReads host = IStreamMintReads(address(this));
        (bool exists,) = host.phase(collectionId, phaseId);
        if (!exists) revert IStreamMintManager.MintPhaseDoesNotExist(collectionId, phaseId);
        config = host.counterConfig(collectionId, phaseId, counterId);
        if (!config.enabled) revert IStreamMintManager.InvalidMintCounter(counterId);
    }

    function _value(uint256 collectionId, bytes32 phaseId, bytes32 counterId, bytes32 subject)
        private
        view
        returns (uint64)
    {
        if (subject == bytes32(0)) revert IStreamMintManager.InvalidMintCounter(counterId);
        address ledger = address(IStreamMintReads(address(this)).mintLedger());
        bytes32 key = StreamMintManagerAccounting.previewValue(
            ledger, collectionId, phaseId, counterId, subject
        );
        return IStreamMintLedger(ledger).counterValue(key);
    }

    function _remaining(IStreamMintLedger.CounterCapMode mode, uint64 cap, uint64 current)
        private
        pure
        returns (uint64)
    {
        if (mode == IStreamMintLedger.CounterCapMode.NONE) {
            return type(uint64).max - current;
        }
        return current >= cap ? 0 : cap - current;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamMintOperationIdentity.sol";
import "./StreamMintCounterPolicy.sol";
import "../../interfaces/stream/mint/IStreamMintCounterReads.sol";

/// @notice Applies immutable scoped policy and inline proof-bound caps to canonical consumptions.
library StreamMintCounterPreparation {
    bytes32 private constant VALUE_KEY_DOMAIN = keccak256("6529STREAM_MINT_COUNTER_VALUE_KEY_V1");
    bytes32 private constant RESOLUTION_DOMAIN =
        keccak256("6529STREAM_MINT_ALLOWLIST_RESOLUTION_V1");

    /// @notice Applies the same original scope and inline Merkle proof to one read-only row.
    function resolveCounter(
        IStreamMintLedger.CounterConsumption memory row,
        IStreamMintManager.MintCounterConfig memory config,
        StreamMintOperationIdentity.CounterContext memory context,
        bytes memory resolverData
    ) external view returns (IStreamMintLedger.CounterConsumption memory) {
        (, IStreamMintCounterPolicy.Definition memory d) =
            StreamMintCounterPolicy.read(context.ledger, config.counterConfigHash);
        _scope(row, config, d.scope, context);
        if (config.capMode == IStreamMintLedger.CounterCapMode.MERKLE_STATIC) {
            IStreamMintCounterPolicy.AllowlistProof memory proof =
                abi.decode(resolverData, (IStreamMintCounterPolicy.AllowlistProof));
            if (keccak256(resolverData) != keccak256(abi.encode(proof))) {
                revert IStreamMintCounterReads.MintCounterProofEncodingInvalid(row.counterId);
            }
            _prove(row, config, d.capRoot, proof, context.manager);
        }
        return row;
    }

    function prepare(
        IStreamMintManager.MintBatch calldata batch,
        uint256 quantity,
        bytes32[] memory ids,
        IStreamMintManager.MintCounterConfig[] memory configs,
        StreamMintOperationIdentity.CounterContext memory context
    ) external view returns (IStreamMintLedger.CounterConsumption[] memory rows) {
        rows = _resolve(batch, quantity, ids, configs, context);
        _checkProjectedValues(context.ledger, rows);
    }

    /// @notice Resolves the identical canonical rows for advisory counter diagnostics.
    /// @dev Only aggregate cap/uint64 checks are deferred to the preview formatter. Execution
    /// always uses prepare(), which retains its original strict checks before returning rows.
    function preview(
        IStreamMintManager.MintBatch calldata batch,
        uint256 quantity,
        bytes32[] memory ids,
        IStreamMintManager.MintCounterConfig[] memory configs,
        StreamMintOperationIdentity.CounterContext memory context
    ) external view returns (IStreamMintLedger.CounterConsumption[] memory rows) {
        return _resolve(batch, quantity, ids, configs, context);
    }

    function _resolve(
        IStreamMintManager.MintBatch calldata batch,
        uint256 quantity,
        bytes32[] memory ids,
        IStreamMintManager.MintCounterConfig[] memory configs,
        StreamMintOperationIdentity.CounterContext memory context
    ) private view returns (IStreamMintLedger.CounterConsumption[] memory rows) {
        rows = StreamMintOperationIdentity.deriveCounterConsumptions(
            batch, quantity, ids, configs, context
        );
        uint256 merkleCount;
        for (uint256 i; i < configs.length; ++i) {
            if (configs[i].capMode == IStreamMintLedger.CounterCapMode.MERKLE_STATIC) {
                ++merkleCount;
            }
        }
        IStreamMintCounterPolicy.AllowlistProof[][] memory proofs;
        if (merkleCount != 0) {
            proofs = abi.decode(batch.resolverData, (IStreamMintCounterPolicy.AllowlistProof[][]));
            if (proofs.length != merkleCount) {
                revert IStreamMintCounterPolicy.MintAllowlistProofCountMismatch(
                    proofs.length, merkleCount
                );
            }
        }
        uint256 cursor;
        uint256 proofIndex;
        for (uint256 i; i < configs.length; ++i) {
            (, IStreamMintCounterPolicy.Definition memory d) =
                StreamMintCounterPolicy.read(context.ledger, configs[i].counterConfigHash);
            uint256 count =
                configs[i].keyMode == IStreamMintManager.CounterKeyMode.CONTEXT ? 1 : quantity;
            bool merkle = configs[i].capMode == IStreamMintLedger.CounterCapMode.MERKLE_STATIC;
            if (merkle) {
                uint256 expected =
                    configs[i].keyMode == IStreamMintManager.CounterKeyMode.PAYER ? 1 : quantity;
                if (proofs[proofIndex].length != expected) {
                    revert IStreamMintCounterPolicy.MintAllowlistProofCountMismatch(
                        proofs[proofIndex].length, expected
                    );
                }
            }
            for (uint256 j; j < count; ++j) {
                IStreamMintLedger.CounterConsumption memory row = rows[cursor++];
                _scope(row, configs[i], d.scope, context);
                if (merkle) {
                    uint256 index =
                        configs[i].keyMode == IStreamMintManager.CounterKeyMode.PAYER ? 0 : j;
                    _prove(row, configs[i], d.capRoot, proofs[proofIndex][index], context.manager);
                }
            }
            if (merkle) ++proofIndex;
        }
    }

    function _checkProjectedValues(
        address ledger,
        IStreamMintLedger.CounterConsumption[] memory rows
    ) private view {
        // Sum the complete batch for every key before the Ledger or Core can write.
        // Repeated keys use each applicable effective cap, including mixed valid leaf presentations.
        for (uint256 i; i < rows.length; ++i) {
            uint256 projected = IStreamMintLedger(ledger).counterValue(rows[i].valueKey);
            for (uint256 j; j < rows.length; ++j) {
                if (rows[i].valueKey == rows[j].valueKey) projected += rows[j].increment;
            }
            if (projected > type(uint64).max) {
                revert IStreamMintLedger.CounterValueOverflow(rows[i].valueKey);
            }
            if (rows[i].cap != 0 && projected > rows[i].cap) {
                revert IStreamMintLedger.CounterCapExceeded(
                    rows[i].valueKey, projected, rows[i].cap
                );
            }
        }
    }

    function _scope(
        IStreamMintLedger.CounterConsumption memory row,
        IStreamMintManager.MintCounterConfig memory config,
        IStreamMintCounterPolicy.CounterScope scope,
        StreamMintOperationIdentity.CounterContext memory context
    ) private pure {
        (uint256 collectionId, bytes32 phaseId) =
            StreamMintCounterPolicy.scopeIds(scope, row.collectionId, row.phaseId);
        if (config.keyMode == IStreamMintManager.CounterKeyMode.CONSTANT) {
            StreamMintOperationIdentity.SubjectContext memory subject;
            subject.chainId = context.chainId;
            subject.ledger = context.ledger;
            subject.collectionId = collectionId;
            subject.phaseId = phaseId;
            subject.counterId = row.counterId;
            row.subjectKey = StreamMintOperationIdentity.subjectKey(config.keyMode, subject);
        }
        row.valueKey = keccak256(
            abi.encode(
                VALUE_KEY_DOMAIN,
                context.manager,
                collectionId,
                phaseId,
                row.counterId,
                row.subjectKey
            )
        );
    }

    function _prove(
        IStreamMintLedger.CounterConsumption memory row,
        IStreamMintManager.MintCounterConfig memory config,
        bytes32 root,
        IStreamMintCounterPolicy.AllowlistProof memory proof,
        address manager
    ) private view {
        address account = config.keyMode == IStreamMintManager.CounterKeyMode.PAYER
            ? row.payer
            : row.recipient;
        StreamMintCounterPolicy.validateSupportedPrice(row.counterId, account, proof);
        bytes32 leaf = StreamMintCounterPolicy.allowlistLeaf(
            manager, row.collectionId, row.phaseId, row.counterId, account, proof
        );
        if (
            proof.maxCount == 0 || proof.maxCount > config.staticCap
                || !StreamMintCounterPolicy.verify(root, leaf, proof.proof)
        ) {
            revert IStreamMintCounterPolicy.MintAllowlistProofInvalid(row.counterId, account);
        }
        row.cap = proof.maxCount;
        row.resolutionHash = keccak256(abi.encode(RESOLUTION_DOMAIN, row.resolutionHash, leaf));
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/mint/IStreamMintCounterPolicy.sol";

/// @notice Canonical counter extension commitments and inline Merkle verification.
library StreamMintCounterPolicy {
    bytes32 internal constant DEFINITION_DOMAIN =
        keccak256("6529STREAM_MINT_COUNTER_DEFINITION_V1");
    bytes32 internal constant ALLOWLIST_LEAF_DOMAIN =
        keccak256("6529STREAM_MINT_ALLOWLIST_LEAF_V1");

    function definitionHash(IStreamMintCounterPolicy.Definition memory d)
        internal
        pure
        returns (bytes32)
    {
        return keccak256(abi.encode(DEFINITION_DOMAIN, d));
    }

    function validateDefinition(IStreamMintCounterPolicy.Definition memory d) internal pure {
        IStreamMintManager.CounterKeyMode key = d.keyMode;
        if (
            key == IStreamMintManager.CounterKeyMode.UNKNOWN
                || key == IStreamMintManager.CounterKeyMode.AUTHORIZER
                || (key == IStreamMintManager.CounterKeyMode.CONTEXT
                    && d.scope == IStreamMintCounterPolicy.CounterScope.GLOBAL)
                || (d.capRoot != bytes32(0)
                    && (d.scope == IStreamMintCounterPolicy.CounterScope.GLOBAL
                        || (key != IStreamMintManager.CounterKeyMode.PAYER
                            && key != IStreamMintManager.CounterKeyMode.RECIPIENT)))
        ) {
            revert IStreamMintCounterPolicy.InvalidCounterDefinition();
        }
    }

    function read(address ledger, bytes32 hash)
        internal
        view
        returns (bool exists, IStreamMintCounterPolicy.Definition memory d)
    {
        // Older ledgers remain usable for their original PHASE policies.
        (bool ok, bytes memory result) = ledger.staticcall{ gas: 30_000 }(
            abi.encodeWithSelector(
                IERC165.supportsInterface.selector, type(IStreamMintCounterPolicy).interfaceId
            )
        );
        if (!ok || result.length != 32 || abi.decode(result, (uint256)) != 1) {
            d.scope = IStreamMintCounterPolicy.CounterScope.PHASE;
            return (false, d);
        }
        (exists, d) =
            IStreamMintCounterPolicy(ledger).counterDefinitionForManager(address(this), hash);
        if (!exists) d.scope = IStreamMintCounterPolicy.CounterScope.PHASE;
    }

    function validateConfig(
        address ledger,
        bytes32 counterId,
        IStreamMintManager.MintCounterConfig memory config
    ) internal view {
        (bool exists, IStreamMintCounterPolicy.Definition memory d) =
            read(ledger, config.counterConfigHash);
        bool merkle = config.capMode == IStreamMintLedger.CounterCapMode.MERKLE_STATIC;
        if (
            (exists
                    && (d.keyMode != config.keyMode
                        || config.capMode == IStreamMintLedger.CounterCapMode.NONE
                        || (d.capRoot != bytes32(0)) != merkle))
                || (merkle && (!exists || config.staticCap == 0))
        ) {
            revert IStreamMintManager.InvalidMintCounter(counterId);
        }
    }

    function scopeIds(
        IStreamMintCounterPolicy.CounterScope scope,
        uint256 collectionId,
        bytes32 phaseId
    ) internal pure returns (uint256, bytes32) {
        if (scope == IStreamMintCounterPolicy.CounterScope.GLOBAL) {
            return (0, bytes32(0));
        }
        if (scope == IStreamMintCounterPolicy.CounterScope.COLLECTION) {
            return (collectionId, bytes32(0));
        }
        return (collectionId, phaseId);
    }

    function allowlistLeaf(
        address manager,
        uint256 collectionId,
        bytes32 phaseId,
        bytes32 counterId,
        address account,
        IStreamMintCounterPolicy.AllowlistProof memory p
    ) internal view returns (bytes32) {
        return keccak256(
            bytes.concat(
                keccak256(
                    abi.encode(
                        ALLOWLIST_LEAF_DOMAIN,
                        block.chainid,
                        manager,
                        collectionId,
                        phaseId,
                        counterId,
                        account,
                        p.maxCount,
                        p.hasPriceOverride,
                        p.priceOverride
                    )
                )
            )
        );
    }

    /// @notice Rejects an undeclared value; enabled prices are interpreted only by sale consumers.
    function validateSupportedPrice(
        bytes32 counterId,
        address account,
        IStreamMintCounterPolicy.AllowlistProof memory proof
    ) internal pure {
        if (!proof.hasPriceOverride && proof.priceOverride != 0) {
            revert IStreamMintCounterPolicy.MintAllowlistPriceOverrideUnsupported(
                counterId, account, proof.hasPriceOverride, proof.priceOverride
            );
        }
    }

    function verify(bytes32 root, bytes32 leaf, bytes32[] memory proof)
        internal
        pure
        returns (bool)
    {
        bytes32 computed = leaf;
        for (uint256 i; i < proof.length; ++i) {
            bytes32 sibling = proof[i];
            computed = computed < sibling
                ? keccak256(abi.encode(computed, sibling))
                : keccak256(abi.encode(sibling, computed));
        }
        return computed == root;
    }
}

