pragma solidity ^0.8.19;

import "./IStreamMintLedger.sol";
import "./compatibility/IStreamMintModuleRegistry.sol";

/// @notice Complete discovery and compatibility API for phase policy and mint execution.
/// @dev Keep own function declarations and nested type ownership stable for ERC165
///      and existing Solidity callers. Execution, Admin, and Reads are caller views.
interface IStreamMintManager {
    /// @notice Launch-supported subject source for a static counter.
    enum CounterKeyMode {
        UNKNOWN,
        CONSTANT,
        PAYER,
        RECIPIENT,
        EXECUTOR,
        AUTHORIZER,
        CONTEXT
    }

    /// @notice Explicit verification path for a normalized batch authorizer.
    enum AuthorizerKind {
        NONE,
        EOA_712,
        ERC1271_712,
        CALLER_ADAPTER
    }

    /// @notice Phase policy fields owned by the manager, not Core.
    struct MintPhaseConfig {
        bool paused;
        uint64 startTime;
        uint64 endTime;
        uint32 maxBatchQuantity;
        bytes32 configHash;
        bytes32 metadataHash;
    }

    /// @notice Manager-side counter policy that is projected into StreamMintLedger.
    struct MintCounterConfig {
        bool enabled;
        CounterKeyMode keyMode;
        IStreamMintLedger.CounterCapMode capMode;
        IStreamMintLedger.CounterDeltaMode deltaMode;
        uint64 staticCap;
        uint64 staticIncrement;
        bytes32 counterConfigHash;
    }

    /// @notice Optional gate module pinned into one phase policy hash.
    struct MintGateConfig {
        address gate;
        bytes32 gateConfigHash;
        bytes32 gateCodehash;
        bytes32 gateMetadataHash;
        uint32 gateSemanticVersion;
        uint32 gateGasLimit;
    }

    /// @notice Canonical batch request shared by single-step and prepared execution.
    struct MintBatch {
        uint256 collectionId;
        bytes32 phaseId;
        address payer;
        address authorizer;
        address[] initialRecipients;
        address[] beneficiaries;
        bytes[] tokenData;
        bytes32[] mintCommitments;
        bytes32 expectedPolicyHash;
        bytes32 authorizationId;
        bytes32 contextHash;
        bytes resolverData;
    }

    /// @notice Reverts when the Core dependency is not a valid StreamCore.
    error InvalidCoreContract(address core);
    /// @notice Reverts when the ledger dependency is not a valid StreamMintLedger.
    error InvalidMintLedgerContract(address mintLedger);
    /// @notice Reverts when a phase identity is invalid.
    error InvalidMintPhase(uint256 collectionId, bytes32 phaseId);
    /// @notice Reverts when a phase has not been configured.
    error MintPhaseDoesNotExist(uint256 collectionId, bytes32 phaseId);
    /// @notice Reverts when initial configuration is attempted for an existing phase.
    error MintPhaseAlreadyConfigured(uint256 collectionId, bytes32 phaseId);
    /// @notice Reverts when a configured phase is paused.
    error MintPhasePaused(uint256 collectionId, bytes32 phaseId);
    /// @notice Reverts when a phase has not started.
    error MintPhaseNotStarted(uint256 collectionId, bytes32 phaseId, uint256 timestamp);
    /// @notice Reverts when a phase has ended.
    error MintPhaseEnded(uint256 collectionId, bytes32 phaseId, uint256 timestamp);
    /// @notice Reverts when the caller may not execute a phase.
    error UnauthorizedMintExecutor(uint256 collectionId, bytes32 phaseId, address executor);
    /// @notice Reverts when an executor address is invalid.
    error InvalidMintExecutor(address executor);
    /// @notice Reverts when a phase would exceed the launch executor hard cap.
    error MintExecutorCountLimitExceeded(uint256 executorCount, uint256 maxExecutorCount);
    /// @notice Reverts when request array lengths do not match.
    error MintArrayLengthMismatch();
    /// @notice Reverts when a request has no token or exceeds the phase cap.
    error MintBatchQuantityLimitExceeded(uint256 quantity, uint256 maxBatchQuantity);
    /// @notice Reverts when a phase batch limit is zero or above the launch hard cap.
    error InvalidMintBatchLimit(uint256 maxBatchQuantity, uint256 maxBatchHardLimit);
    /// @notice Reverts when a phase configures more counters than launch allows.
    error MintCounterCountLimitExceeded(uint256 counterCount, uint256 maxCounterCount);
    /// @notice Deprecated compatibility error; counter cap enforcement now reverts from the ledger.
    error MintCounterCapExceeded(bytes32 valueKey, uint256 projectedValue, uint256 cap);
    /// @notice Reverts when a token recipient or beneficiary is zero.
    error InvalidMintRecipient(uint256 index, address initialRecipient, address beneficiary);
    /// @notice Reverts when a configured counter is invalid for the launch-static manager.
    error InvalidMintCounter(bytes32 counterId);
    /// @notice Reverts when a counter ID appears more than once in a phase.
    error DuplicateMintCounter(bytes32 counterId);
    /// @notice Reverts when a counter mode is reserved for a future manager.
    error UnsupportedMintCounterMode(bytes32 counterId);
    /// @notice Reverts when a counter subject cannot be derived.
    error MintCounterSubjectMissing(bytes32 counterId, CounterKeyMode keyMode);
    /// @notice Reverts when a caller does not bind execution to the active policy hash.
    error MintPolicyHashRequired(uint256 collectionId, bytes32 phaseId);
    /// @notice Reverts when a caller supplies a stale or unexpected phase policy hash.
    error MintPolicyHashMismatch(bytes32 expectedPolicyHash, bytes32 activePolicyHash);
    /// @notice Reverts when a caller does not provide a replay-protected authorization ID.
    error MintAuthorizationRequired(uint256 collectionId, bytes32 phaseId);
    /// @notice Reverts when the module registry dependency is invalid.
    error InvalidMintModuleRegistry(address registry);
    /// @notice Reverts when a configured gate is invalid for launch policy.
    error InvalidMintGate(address gate);
    /// @notice Reverts when a gate is not active for the required interface.
    error MintGateNotActive(address gate);
    /// @notice Reverts when a gate's codehash no longer matches the phase pin.
    error MintGateCodehashChanged(address gate, bytes32 expected, bytes32 actual);
    /// @notice Reverts when gate validation fails.
    error MintGateValidationFailed(address gate);
    /// @notice Reverts when a gate returns unsupported nullifiers.
    error MintGateNullifiersUnsupported(bytes32 nullifier);
    /// @notice Reverts when a gate returns more nullifiers than the launch hard cap.
    error MintGateNullifierCountExceeded(uint256 count, uint256 maximum);
    /// @notice Reverts when a gate returns too small a quantity limit.
    error MintGateQuantityExceeded(uint256 quantity, uint256 maxQuantity);
    /// @notice Reverts when request and gate authorization IDs conflict.
    error MintGateAuthorizationMismatch(
        bytes32 requestAuthorizationId, bytes32 gateAuthorizationId
    );
    /// @notice Reverts when request and gate authorizers conflict.
    error MintGateAuthorizerMismatch(address requestAuthorizer, address gateAuthorizer);
    /// @notice Reverts when a gate returns no durable evidence hash.
    error MintGateHashRequired(address gate);
    /// @notice Reverts when the normalized authorizer kind/address pair is invalid.
    error MintInvalidAuthorizerKind(uint8 kind, address authorizer);
    /// @notice Reverts when an operation nonce range would overflow.
    error MintOperationNonceOverflow(uint256 firstOperationNonce, uint256 quantity);
    /// @notice Reverts when a derived batch root is zero.
    error MintOperationRootRequired();
    /// @notice Reverts when a derived token operation ID is zero.
    error MintOperationIdRequired(uint256 tokenIndex);
    /// @notice Reverts when two token indices derive the same operation ID.
    error MintOperationIdDuplicate(uint256 firstIndex, uint256 secondIndex);

    /// @notice Emitted when a phase is configured and registered in the ledger.
    event MintPhaseConfigured(
        uint256 indexed collectionId,
        bytes32 indexed phaseId,
        bytes32 indexed policyHash,
        uint64 startTime,
        uint64 endTime,
        uint32 maxBatchQuantity,
        bytes32 configHash,
        bytes32 metadataHash,
        address admin
    );
    /// @notice Emitted when a phase pause flag changes.
    event MintPhasePausedEvent(
        uint256 indexed collectionId,
        bytes32 indexed phaseId,
        bool paused,
        bytes32 policyHash,
        address admin
    );
    /// @notice Emitted when an executor is enabled or disabled for a phase.
    event MintPhaseExecutorUpdated(
        uint256 indexed collectionId,
        bytes32 indexed phaseId,
        address indexed executor,
        bool allowed,
        bytes32 policyHash,
        address admin
    );
    /// @notice Emitted for each counter configured under a phase policy.
    event MintCounterConfigured(
        uint256 indexed collectionId,
        bytes32 indexed phaseId,
        bytes32 indexed counterId,
        CounterKeyMode keyMode,
        IStreamMintLedger.CounterCapMode capMode,
        IStreamMintLedger.CounterDeltaMode deltaMode,
        uint64 staticCap,
        uint64 staticIncrement,
        bytes32 counterConfigHash,
        bytes32 policyHash
    );
    /// @notice Emitted when a phase binds an optional gate module.
    event MintPhaseGateConfigured(
        uint256 indexed collectionId,
        bytes32 indexed phaseId,
        address indexed gate,
        bytes32 gateConfigHash,
        bytes32 gateCodehash,
        bytes32 gateMetadataHash,
        uint32 gateSemanticVersion,
        uint32 gateGasLimit,
        bytes32 policyHash
    );
    /// @notice Emitted after a gate validates one prepared mint batch.
    event MintGateValidated(
        uint256 indexed collectionId,
        bytes32 indexed phaseId,
        address indexed gate,
        bytes32 authorizationId,
        address authorizer,
        uint256 quantity,
        bytes32 contextHash,
        bytes32 gateHash,
        bytes32 policyHash
    );
    /// @notice Emitted once after every successful manager batch.
    event MintBatchExecuted(
        uint16 schemaVersion,
        bytes32 indexed operationRoot,
        uint256 indexed collectionId,
        bytes32 indexed phaseId,
        address executor,
        address payer,
        address authorizer,
        uint256 firstTokenId,
        uint256 quantity,
        bytes32 contextHash,
        bytes32 gateHash,
        bytes32 currentPolicyHash,
        bytes32 boundPolicyHash
    );
    /// @notice Emitted with manager phase context for authorization consumption.
    event MintAuthorizationConsumed(
        uint16 schemaVersion,
        uint256 indexed collectionId,
        bytes32 indexed phaseId,
        bytes32 indexed authorizationId,
        bytes32 boundPolicyHash,
        bytes32 operationRoot
    );
    /// @notice Emitted once per immediate single-step token.
    event MintTokenExecuted(
        uint16 schemaVersion,
        bytes32 indexed operationId,
        uint256 indexed tokenId,
        bytes32 indexed operationRoot,
        uint256 collectionId,
        bytes32 phaseId,
        uint256 tokenIndex,
        address initialRecipient,
        address beneficiary,
        bytes32 tokenDataHash,
        bytes32 mintCommitment
    );
    /// @notice Emitted after Core records a prepared token.
    event PreparedMintStarted(
        uint16 schemaVersion,
        bytes32 indexed operationId,
        uint256 indexed tokenId,
        uint256 indexed collectionId,
        bytes32 operationRoot,
        uint256 collectionSerial,
        address beneficiary,
        bytes32 tokenDataHash,
        bytes32 mintCommitment
    );
    /// @notice Emitted after Core completes a prepared token.
    event PreparedMintCompleted(
        uint16 schemaVersion,
        bytes32 indexed operationId,
        uint256 indexed tokenId,
        uint256 indexed collectionId,
        bytes32 operationRoot,
        address initialRecipient
    );

    /// @notice Returns true for deployment validation.
    function isStreamMintManager() external view returns (bool);
    /// @notice Configures and registers a launch-static phase policy.
    function configurePhase(
        uint256 collectionId,
        bytes32 phaseId,
        MintPhaseConfig calldata config,
        MintGateConfig calldata gateConfig,
        bytes32[] calldata counterIds,
        MintCounterConfig[] calldata counterConfigs
    ) external returns (bytes32 policyHash);
    /// @notice Enables or disables a caller for a configured phase.
    function setPhaseExecutor(uint256 collectionId, bytes32 phaseId, address executor, bool allowed)
        external;
    /// @notice Pauses or unpauses a configured phase.
    function setPhasePaused(uint256 collectionId, bytes32 phaseId, bool paused) external;
    /// @notice Executes the immediate Core manager path atomically.
    function executeSingleStepMint(MintBatch calldata batch, bytes calldata gateData)
        external
        returns (uint256[] memory tokenIds, bytes32 operationRoot, bytes32[] memory operationIds);
    /// @notice Executes the prepared Core manager path atomically.
    function executePreparedMint(MintBatch calldata batch, bytes calldata gateData)
        external
        returns (uint256[] memory tokenIds, bytes32 operationRoot, bytes32[] memory operationIds);
    /// @notice Previews the single-step identity transcript for the current manager state.
    /// @dev Matches execution only while the nonce, phase policy/grace, and gate result stay unchanged.
    function previewSingleStepMintOperation(MintBatch calldata batch, bytes calldata gateData)
        external
        view
        returns (bytes32 operationRoot, bytes32[] memory operationIds);
    /// @notice Returns the first unreserved manager operation nonce.
    function nextOperationNonce() external view returns (uint256);
    /// @notice Returns immutable phase config plus existence.
    function phase(uint256 collectionId, bytes32 phaseId)
        external
        view
        returns (bool exists, MintPhaseConfig memory config);
    /// @notice Returns the active manager policy hash for a phase.
    function phasePolicyHash(uint256 collectionId, bytes32 phaseId) external view returns (bytes32);
    /// @notice Returns manager-scoped authorization replay state independent of the caller.
    function isAuthorizationUsed(bytes32 authorizationId) external view returns (bool);
    /// @notice Returns manager-scoped nullifier replay state independent of the caller.
    function isNullifierUsed(bytes32 nullifier) external view returns (bool);
    /// @notice Returns manager-scoped operation-root replay state independent of the caller.
    function isOperationRootUsed(bytes32 operationRoot) external view returns (bool);
    /// @notice Returns the immediate predecessor policy and its grace expiry.
    function phasePolicyGrace(uint256 collectionId, bytes32 phaseId)
        external
        view
        returns (bytes32 previousPolicyHash, uint64 graceUntil);
    /// @notice Returns whether an executor may call a phase.
    function phaseExecutor(uint256 collectionId, bytes32 phaseId, address executor)
        external
        view
        returns (bool);
    /// @notice Returns the ordered counter IDs for a phase.
    function phaseCounterIds(uint256 collectionId, bytes32 phaseId)
        external
        view
        returns (bytes32[] memory);
    /// @notice Returns one manager-side counter config.
    function counterConfig(uint256 collectionId, bytes32 phaseId, bytes32 counterId)
        external
        view
        returns (MintCounterConfig memory);
    /// @notice Returns one phase's optional gate config.
    function phaseGate(uint256 collectionId, bytes32 phaseId)
        external
        view
        returns (MintGateConfig memory);
    /// @notice Previews the manager-derived subject key for one token/counter context.
    function previewSubjectKey(
        CounterKeyMode keyMode,
        uint256 collectionId,
        bytes32 phaseId,
        bytes32 counterId,
        address payer,
        address recipient,
        address executor,
        address authorizer,
        bytes32 contextHash
    ) external view returns (bytes32);
    /// @notice Previews the canonical ledger value key for a derived subject.
    function previewCounterValueKey(
        uint256 collectionId,
        bytes32 phaseId,
        bytes32 counterId,
        bytes32 subjectKey
    ) external view returns (bytes32);
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @notice Durable outside-Core accounting ledger for launch mint counters.
interface IStreamMintLedger {
    /// @notice Counter cap source for launch mint accounting.
    enum CounterCapMode {
        NONE,
        STATIC,
        RESOLVER,
        MERKLE_STATIC
    }

    /// @notice Counter increment source for launch mint accounting.
    enum CounterDeltaMode {
        STATIC,
        RESOLVER
    }

    /// @notice Registered accounting policy for one counter ID.
    struct LedgerCounterPolicy {
        bool enabled;
        CounterCapMode capMode;
        CounterDeltaMode deltaMode;
        uint64 staticCap;
        uint64 staticIncrement;
        bytes32 counterConfigHash;
    }

    /// @notice One resolved static counter increment prepared by the mint manager.
    struct CounterConsumption {
        bytes32 valueKey;
        uint256 collectionId;
        bytes32 phaseId;
        bytes32 counterId;
        bytes32 subjectKey;
        address payer;
        address recipient;
        address authorizer;
        address executor;
        uint64 increment;
        uint64 cap;
        bytes32 contextHash;
        bytes32 resolutionHash;
    }

    /// @notice Immediate predecessor policy retained for a bounded grace window.
    struct LedgerPolicyGrace {
        bytes32 previousPolicyHash;
        uint64 previousPolicyRevision;
        uint64 previousPolicyGraceUntil;
    }

    /// @notice Reverts when a caller is not authorized to write ledger state.
    error UnauthorizedLedgerWriter(address writer);
    /// @notice Reverts when the owner tries to configure an invalid writer.
    error InvalidLedgerWriter(address writer);
    /// @notice Reverts when a phase policy registration or lookup is invalid.
    error InvalidPhasePolicy(address manager, uint256 collectionId, bytes32 phaseId);
    /// @notice Reverts when a counter policy is invalid or unsupported for launch.
    error InvalidCounterPolicy(bytes32 counterId);
    /// @notice Reverts when a phase policy repeats a counter ID.
    error DuplicateCounterPolicy(bytes32 counterId);
    /// @notice Reverts when counter ID and counter policy arrays differ in length.
    error CounterPolicyLengthMismatch(uint256 counterIds, uint256 counterPolicies);
    /// @notice Reverts when a consumed counter has no registered policy.
    error CounterPolicyNotRegistered(
        address manager, uint256 collectionId, bytes32 phaseId, bytes32 counterId
    );
    /// @notice Reverts when a consumed counter does not match its registered policy.
    error CounterPolicyMismatch(bytes32 counterId);
    /// @notice Reverts when a supplied value key does not match the ledger key derivation.
    error CounterValueKeyMismatch(bytes32 suppliedValueKey, bytes32 expectedValueKey);
    /// @notice Reverts when a static counter increment would exceed its cap.
    error CounterCapExceeded(bytes32 valueKey, uint256 projectedValue, uint256 cap);
    /// @notice Reverts when a counter increment would overflow uint64 storage.
    error CounterValueOverflow(bytes32 valueKey);
    /// @notice Reverts when an authorization ID has already been consumed.
    error AuthorizationAlreadyConsumed(bytes32 authorizationId);
    /// @notice Reverts when a nullifier has already been consumed.
    error NullifierAlreadyConsumed(bytes32 nullifier);
    /// @notice Reverts when a phase policy grace deadline is invalid.
    error InvalidPolicyGrace(uint64 graceUntil);
    /// @notice Reverts when a batch operation root is zero.
    error OperationRootRequired();
    /// @notice Reverts when a manager already consumed a batch operation root.
    error OperationRootAlreadyConsumed(address manager, bytes32 operationRoot);

    /// @notice Emitted when the owner enables or disables a ledger writer.
    event MintLedgerWriterUpdated(address indexed writer, bool allowed);
    /// @notice Emitted when a manager registers a phase policy hash.
    event MintLedgerPhasePolicyRegistered(
        address indexed manager,
        uint256 indexed collectionId,
        bytes32 indexed phaseId,
        bytes32 policyHash
    );
    /// @notice Emitted for each counter policy registered under a phase policy.
    event MintLedgerCounterPolicyRegistered(
        address indexed manager,
        uint256 indexed collectionId,
        bytes32 indexed phaseId,
        bytes32 counterId,
        CounterCapMode capMode,
        CounterDeltaMode deltaMode,
        uint64 staticCap,
        uint64 staticIncrement,
        bytes32 counterConfigHash,
        bytes32 policyHash
    );
    /// @notice Emitted when a registered counter value is incremented.
    event MintLedgerCounterConsumed(
        uint16 schemaVersion,
        bytes32 indexed valueKey,
        uint256 indexed collectionId,
        bytes32 indexed phaseId,
        address manager,
        bytes32 counterId,
        bytes32 subjectKey,
        uint64 increment,
        uint64 newValue,
        uint64 cap,
        bytes32 boundPolicyHash,
        bytes32 operationRoot
    );
    /// @notice Emitted with non-indexed context for reconstructing a counter increment.
    event MintLedgerCounterConsumptionContext(
        uint16 schemaVersion,
        bytes32 indexed valueKey,
        bytes32 indexed counterId,
        bytes32 indexed subjectKey,
        address manager,
        address payer,
        address recipient,
        address authorizer,
        address executor,
        bytes32 contextHash,
        bytes32 resolutionHash
    );
    /// @notice Emitted when an authorization ID is consumed.
    event MintLedgerAuthorizationConsumed(
        uint16 schemaVersion,
        bytes32 indexed authorizationId,
        bytes32 indexed operationRoot,
        address indexed manager,
        bytes32 boundPolicyHash
    );
    /// @notice Emitted when a manager consumes a nullifier.
    event MintLedgerNullifierConsumed(
        uint16 schemaVersion,
        bytes32 indexed nullifier,
        bytes32 indexed operationRoot,
        address indexed manager,
        bytes32 boundPolicyHash
    );
    /// @notice Emitted exactly once when a manager consumes a batch operation root.
    event MintLedgerOperationRootConsumed(
        uint16 schemaVersion,
        bytes32 indexed operationRoot,
        address indexed manager,
        bytes32 currentPolicyHash,
        bytes32 indexed boundPolicyHash,
        bytes32 authorizationId
    );
    /// @notice Emitted when a policy rotation records or clears predecessor grace.
    event MintLedgerPolicyGraceSet(
        uint16 schemaVersion,
        uint256 indexed collectionId,
        bytes32 indexed phaseId,
        address indexed manager,
        bytes32 previousPolicyHash,
        bytes32 newPolicyHash,
        uint64 graceUntil
    );

    /// @notice Returns true for deployment validation.
    function isStreamMintLedger() external pure returns (bool);

    /// @notice Enables or disables a deployed manager contract as an authorized ledger writer.
    function setLedgerWriter(address writer, bool allowed) external;

    /// @notice Returns whether an address may register and consume ledger state.
    function ledgerWriter(address writer) external view returns (bool);

    /// @notice Registers one launch-static phase policy for the calling manager.
    function registerPhasePolicy(
        address manager,
        uint256 collectionId,
        bytes32 phaseId,
        bytes32 policyHash,
        bytes32[] calldata counterIds,
        LedgerCounterPolicy[] calldata counterPolicies,
        uint64 graceUntil
    ) external;

    /// @notice Consumes one manager-scoped operation root and its accounting facts.
    function consume(
        uint256 collectionId,
        bytes32 phaseId,
        CounterConsumption[] calldata consumptions,
        bytes32 authorizationId,
        bytes32[] calldata nullifiers,
        bytes32 boundPolicyHash,
        bytes32 operationRoot
    ) external;

    /// @notice Returns the registered policy hash for a manager phase.
    function registeredPhasePolicyHash(address manager, uint256 collectionId, bytes32 phaseId)
        external
        view
        returns (bytes32);

    /// @notice Returns the registered static policy for one manager phase counter.
    function registeredCounterPolicy(
        address manager,
        uint256 collectionId,
        bytes32 phaseId,
        bytes32 counterId
    ) external view returns (LedgerCounterPolicy memory);

    /// @notice Returns the durable uint64 value for one ledger counter key.
    /// @dev Counter values are not reset by phase policy re-registration.
    function counterValue(bytes32 valueKey) external view returns (uint64);

    /// @notice Derives the canonical value key for a manager counter subject.
    function deriveCounterValueKey(
        address manager,
        uint256 collectionId,
        bytes32 phaseId,
        bytes32 counterId,
        bytes32 subjectKey
    ) external pure returns (bytes32);

    /// @notice Returns whether a manager has already consumed an authorization ID.
    function isManagerAuthorizationUsed(address manager, bytes32 authorizationId)
        external
        view
        returns (bool);

    /// @notice Returns whether a manager has already consumed a nullifier.
    function isManagerNullifierUsed(address manager, bytes32 nullifier) external view returns (bool);

    /// @notice Returns whether a manager has already consumed an operation root.
    function isManagerOperationRootUsed(address manager, bytes32 operationRoot)
        external
        view
        returns (bool);

    /// @notice Returns the immediate predecessor grace tuple for a manager phase.
    function policyGrace(address manager, uint256 collectionId, bytes32 phaseId)
        external
        view
        returns (
            bytes32 previousPolicyHash,
            uint64 previousPolicyRevision,
            uint64 previousPolicyGraceUntil
        );
}
